\label{Pic}
For $g \geq 2$, the integral Picard groups of the Hurwitz stacks are as follows.
\begin{enumerate}
    \item We have
    \[
    \operatorname{Pic}(\mathscr{H}_{4,g})=\begin{cases} \mathbb{Z} \oplus \mathbb{Z}/10\mathbb{Z} & \text{if $g = 2$} \\ \mathbb{Z}\oplus \mathbb{Z} & \text{if $g \geq 3$.} \end{cases}
    \]
    \item We have 
    \[
    \operatorname{Pic}(\mathscr{H}_{5,g})=\begin{cases} \mathbb{Z} \oplus \mathbb{Z}/10\mathbb{Z} &\text{if $g = 2$} \\ \mathbb{Z}\oplus \mathbb{Z} & \text{if $g \geq 3$.}\end{cases}
    \]
\end{enumerate}

\label{mc}
For $g \geq 2$, the integral Picard groups of the simply branched Hurwitz stacks are as follows:
\begin{enumerate}
    \item We have
    \[ \operatorname{Pic}(\mathscr{H}_{3,g}^s) =
    \begin{cases} \mathbb{Z}/2\mathbb{Z} & \text{if $g = 2$} \\ \mathbb{Z}/(4g + 6)\mathbb{Z} \oplus \mathbb{Z}/3\mathbb{Z} & \text{if $g \geq 3$ odd} \\
    \mathbb{Z}/(8g + 12)\mathbb{Z} \oplus \mathbb{Z}/3\mathbb{Z}  & \text{if $g \geq 3$ even} 
    \end{cases} \]
    \item We have
    \[\operatorname{Pic}(\mathscr{H}_{4,g}^s) = \begin{cases} \mathbb{Z}/18\mathbb{Z} \oplus \mathbb{Z}/2\mathbb{Z} &\text{if $g = 2$} \\ \mathbb{Z}/(8g+20)\mathbb{Z} \oplus \mathbb{Z}/12\mathbb{Z} & \text{if $g \geq 3$ odd} \\
    \mathbb{Z}/(4g+10)\mathbb{Z} \oplus \mathbb{Z}/12\mathbb{Z} & \text{if $g \geq 3$ even.} 
    \end{cases} \]
    \item We have
    \[\operatorname{Pic}(\mathscr{H}_{5,g}^s) = \begin{cases}
    \mathbb{Z}/44\mathbb{Z} \oplus \mathbb{Z}/2\mathbb{Z} &\text{if $g = 2$} \\
    \mathbb{Z}/(4g + 14)\mathbb{Z} \oplus \mathbb{Z}/12\mathbb{Z} & \text{if $g \geq 3$ odd} \\
    \mathbb{Z}/(8g+28)\mathbb{Z} \oplus \mathbb{Z}/12\mathbb{Z} & \text{if $g \geq 3$ even.}
    \end{cases}\]
\end{enumerate}

\label{Stacks}
Let $r,d$ be nonnegative integers. 
\begin{enumerate}
    \item The objects of $\mathscr{V}_{r,d}$ are pairs $(P\rightarrow S, E)$ where $P\rightarrow S$ is a $\mathbb{P}^1$-fibration over a $k$-scheme $S$ and $E$ is a locally free sheaf of rank $r$ on $P$ whose restriction to each of the fibers of $P\rightarrow S$ is globally generated of degree $d$. A morphism between objects $(P\rightarrow S, E)$ and $(P'\rightarrow S', E')$ is a Cartesian diagram
    \[
    \begin{tikzcd}
P' \arrow[d] \arrow[r, "F"] & P \arrow[d] \\
S' \arrow[r]                & S          
\end{tikzcd}
    \]
    together with an isomorphism $\phi:F^*E\rightarrow E'$.
    \item The objects of $\mathcal{V}_{r,d}$ are triples $(S, V, E)$ where $S$ is a $k$-scheme, $V$ is a rank $2$ vector bundle on $S$ with trivial determinant, and $E$ is a rank $r$ vector bundle on $\mathbb{P} V$ whose restrictions to the fibers of $\mathbb{P} V \rightarrow S$  are globally generated of degree $d$. A morphism between objects $(S,V,E)$ and $(S',V',E')$ is a Cartesian diagram
     \[
    \begin{tikzcd}
\mathbb{P} V' \arrow[d] \arrow[r, "F"] & \mathbb{P} V \arrow[d] \\
S' \arrow[r]                & S          
\end{tikzcd}
    \]
    together with an isomorphism $\phi:F^*E\rightarrow E'$.
\end{enumerate}

\label{int-pic}
The natural map $\mathcal{V}_{r,d} \times_{\operatorname{BSL}_2} \mathcal{V}_{s,e} \to \mathscr{V}_{r,d} \times_{\operatorname{BPGL}_2} \mathscr{V}_{s,e}$ induces an inclusion 
\[\operatorname{Pic}(\mathscr{V}_{r,d} \times_{\operatorname{BPGL}_2} \mathscr{V}_{s,e}) \hookrightarrow \operatorname{Pic}(\mathcal{V}_{r,d} \times_{\operatorname{BSL}_2} \mathcal{V}_{s,e}),\]
whose image is the subgroup generated by 
\begin{equation} \label{gens1}
\begin{cases} t_1, u_1, v_1, w_1 & \text{if $d, e$ both even} \\
2t_1, u_1, v_1, w_1 & \text{if $d$ odd and $e$ even} \\
t_1, u_1, 2v_1, w_1 & \text{if $d$ even and $e$ odd} \\
t_1 - v_1, 2t_1, u_1, w_1 & \text{if $d, e$ both odd,} \end{cases}
\end{equation}
or equivalently by
\begin{equation} \label{gens2}
\begin{cases}
a_1, a_2', b_1, b_2'  & \text{if $d, e$ both even}\\
2a_1, a_2', b_1, b_2'& \text{if $d$ odd and $e$ even}  \\
a_1, a_2', 2b_1, b_2' & \text{if $d$ even and $e$ odd}  \\
a_1 - b_1, 2a_1, a_2', b_2' & \text{if $d, e$ both odd.}
\end{cases}
\end{equation}

\label{comparison}
Let $X' \subset X$ be an open substack. Given a smooth map $f: Y \to X$, let $Y' \subset Y$ be the preimage of $X'$. 
If $\operatorname{Pic}(X) \to \operatorname{Pic}(Y)$ is injective, then $\operatorname{Pic}(X') \to \operatorname{Pic}(Y')$ is injective.

It suffices to treat the 
case when $X' \subset X$ is the complement of an irreducible divisor $D$.  (Removing any component of codimension two or more from $X$ does not change $\operatorname{Pic}(X)$; if $X'$ is the complement of a reducible divisor, then we just apply the irreducible case to each component in turn.)

Because $f: Y \to X$ is smooth, $Y' \subset Y$ is the complement of the irreducible divisor $f^{-1}(D)$, which has class $f^*[D]$.
Let $\langle [D] \rangle$ denote the subgroup of $\operatorname{Pic}(X)$ generated by the fundamental class of $D$ and similarly for $\langle f^*[D] \rangle$ inside $\operatorname{Pic}(Y)$.
We therefore have a diagram of exact sequences where the left vertical map is surjective.
\begin{center}
\begin{tikzcd}
0 \arrow{r} &\langle[D] \rangle \arrow{r} \arrow{d} & \operatorname{Pic}(X) \arrow[hook]{d} \arrow{r} & \operatorname{Pic}(X') \arrow{r} \arrow{d} & 0 \\
0 \arrow{r} &\langle f^*[D] \rangle \arrow{r} & \operatorname{Pic}(Y) \arrow{r} & \operatorname{Pic}(Y') \arrow{r} & 0.
\end{tikzcd}
\end{center}
The result now follows from the snake lemma.

Following the notation of \cite{DP},
let $M(E, F) \subset \mathscr{H}_{4,g}$ denote the locus of covers $\alpha$ with $E_\alpha \cong E$ and $F_\alpha \cong F$. 
The complement of $\mathscr{H}'_{4,g}\subset \mathscr{H}_{4,g}$ is the union of $M(E, F)$ such that
\begin{equation} \label{cc4}
h^1(\mathbb{P}^1, F^\vee \otimes \operatorname{Sym}^2 E) > 0.
\end{equation}
If $E = \mathcal{O}(e_1) \oplus \mathcal{O}(e_2) \oplus \mathcal{O}(e_3)$ with $e_1 \leq e_2 \leq e_3$ and $F = \mathcal{O}(f_1) \oplus \mathcal{O}(f_2)$ with $f_1 \leq f_2$, then \eqref{cc4} is equivalent to $2e_1 - f_1 \leq -2$.

Next, let
$E_{\operatorname{gen}}$ and $F_{\operatorname{gen}}$ denote the balanced bundles of rank $3$ and $2$ and degree $g+3$.
First note that $h^1(F_{\operatorname{gen}}^\vee \otimes \operatorname{Sym}^2 E_{\operatorname{gen}}) = 0$: this is equivalent to $2 \lfloor \frac{g+3}{3} \rfloor - \lceil \frac{g+3}{2} \rceil \geq -1$.
This says that $M(E_{\operatorname{gen}}, F_{\operatorname{gen}}) \subseteq \mathscr{H}_{4,g}'$. Hence, any divisorial component of $\mathscr{H}_{4,g} \smallsetminus \mathscr{H}_{4,g}'$ is contained in a divisorial component of $\mathscr{H}_{4,g} \smallsetminus M(E_{\operatorname{gen}}, F_{\operatorname{gen}})$.

Next, let us define bundles that are ``one-off" from balanced
\begin{align*}
    F_1 &:= \mathcal{O}(n-1) \oplus \mathcal{O}(n+1) & \qquad & \text{if $n = \frac{g+3}{2}$ is an integer} \\
    E_1 &:= \mathcal{O}(m-1) \oplus \mathcal{O}(m) \oplus \mathcal{O}(m+1) & \qquad &\text{if $m = \frac{g+3}{3}$ is an integer.}
\end{align*}
In \cite[p. 20]{DP}, Deopurkar--Patel enumerate the divisorial components of $\mathscr{H}_{4,g} \smallsetminus M(E_{\operatorname{gen}}, F_{\operatorname{gen}})$ and show that, for $g \neq 3$, they are always of the form \begin{align}
    &\overline{M(E_{\operatorname{gen}}, F_1)} &\qquad &\text{if $2 \mid g+3$} \label{oo} \\
    &\overline{M(E_1, F_{\operatorname{gen}})} &\qquad &\text{if $3 \mid g+3$}. \label{ooo}
\end{align}
Note that we are using the irreducibility of $M$ and $CE$ in \cite[Propositions 4.5 and 4.7]{DP} to write these divisors as the closures above.
Meanwhile, when $g = 3$, the stratum
\begin{equation} \label{weird3}
\overline{M(E_1, F_1)} = \overline{M(\mathcal{O}(1) \oplus \mathcal{O}(2) \oplus \mathcal{O}(3), \mathcal{O}(2) \oplus \mathcal{O}(4))} 
\end{equation}
is also a divisor. This divisor does not lie in $\mathscr{H}_{4,g}'$.


One readily checks that
\begin{equation} \label{van1}
h^1(F_1^\vee \otimes \operatorname{Sym}^2 E_{\operatorname{gen}}) = h^1(F_{\operatorname{gen}}^\vee \otimes \operatorname{Sym}^2 E_1) = 0.
\end{equation}
Hence, when they are defined, $\mathscr{H}_{4,g}'$ contains each of 
\[M(E_{\operatorname{gen}}, F_{\operatorname{gen}}), \quad M(E_{\operatorname{gen}}, F_1), \quad M(E_1, F_{\operatorname{gen}}),\]
and, for $g \neq 3$, all other possible $M(E, F)$ have codimension at least $2$.
